// Windows-x64-ABI forwarders to the real Vulkan functions (generated by gen_vk_thunks.py).
#ifndef KYTY_TOOLS_FSR4FG_VK_THUNKS_H_
#define KYTY_TOOLS_FSR4FG_VK_THUNKS_H_
#include <vulkan/vulkan_core.h>

// Resolves every command: through gdpa(device) when there is a device, else gipa(instance). Returns how many resolved.
unsigned VkThunksBind(PFN_vkGetInstanceProcAddr gipa, VkInstance instance, PFN_vkGetDeviceProcAddr gdpa, VkDevice device);
// The ms_abi function to hand AMD's DLL for `name` (an override if set); NULL when the driver does not provide it.
void* VkThunkLookup(const char* name);
// The driver's own (System V) function for `name`, for overrides to forward to.
void* VkThunkReal(const char* name);
// Makes VkThunkLookup return `replacement` (an ms_abi function) for `name`.
int      VkThunkOverride(const char* name, void* replacement);
unsigned VkThunkCount(void);

#endif
